CREATE PROCEDURE GetEmployeeByID
@EmployeeID INT
AS
BEGIN
  SELECT * FROM Employees WHERE EmployeeID = @EmployeeID;
END;

CREATE PROCEDURE GetEmployeeByID
Declare @EmployeeID INT
AS
BEGIN
  SELECT * FROM Employees WHERE EmployeeID = @EmployeeID;
END;

CREATE PROCEDURE GetEmployeeByID
@EmployeeID INT
AS
BEGIN
  SELECT * FROM Employees;
END;

CREATE PROCEDURE GetEmployeeByID
AS
BEGIN
  Declare @EmployeeID INT
  SELECT * FROM Employees WHERE EmployeeID = @EmployeeID;
END;

explanation:
🎯 Đáp án đúng: A (A: CREATE PROCEDURE GetEmployeeByID
@EmployeeID INT
AS
BEGIN
  SELECT * FROM Employees WHERE EmployeeID = @EmployeeID;
END;)

📝 Dịch đề:
Tạo một Stored Procedure có tên `GetEmployeeByID` nhận vào `@EmployeeID INT` và trả về tên nhân viên từ bảng `Employees`. Câu lệnh nào còn thiếu ở dòng `...`?
CREATE PROCEDURE GetEmployeeByID
    @EmployeeID INT
AS
BEGIN
    ...
END;

📋 Dịch đáp án:
- A: CREATE PROCEDURE GetEmployeeByID
@EmployeeID INT
AS
BEGIN
  SELECT * FROM Employees WHERE EmployeeID = @EmployeeID;
END;

📌 Giải thích chi tiết từng bước (Vì sao chọn):
Cú pháp tạo Stored Procedure có tham số đầu vào trong SQL Server là: `CREATE PROCEDURE ProcedureName @parameter datatype AS BEGIN ... END`. Không dùng từ khóa `DECLARE` cho tham số đầu vào (nên B và D sai), và trong thân thủ tục phải lọc `WHERE EmployeeID = @EmployeeID` để lấy đúng nhân viên theo mã được truyền vào (nên C sai, A đúng).

💡 Mẹo nhớ: Đáp án A (CREATE PROCEDURE GetEmployeeByID
@EmployeeID INT
AS
BEGIN
  SELECT * FROM Employees WHERE EmployeeID = @EmployeeID;
END;)

question_translation:
Cho lược đồ quan hệ: `Laptop(model, speed, ram, hd, price)`.
Hàm dưới đây sẽ trả về kết quả gì?
CREATE FUNCTION fn_test(@model VARCHAR(50))
RETURNS INT
AS
BEGIN
    DECLARE @price INT;
    SELECT @price = price FROM Laptop WHERE model = @model;
    RETURN @price;
END

